items := []int{1, 2, 3}
var wg sync.WaitGroup
var v int
for _, v = range items {
	wg.Add(1)
	go func() {
		defer wg.Done()
		fmt.Println(v)
	}()
}
wg.Wait()

var wg sync.WaitGroup
var results []int
for i := 0; i < 3; i++ {
	wg.Add(1)
	go func() {
		defer wg.Done()
		results = append(results, i*10)
	}()
}
wg.Wait()
fmt.Println(results)

